@media(max-width:700px){.promo-banner{flex-wrap:wrap;gap:.35rem;text-align:center}.promo-banner span{width:100%}.promo-modal{gap:.72rem;padding:1.75rem 1.25rem 1.4rem;border-radius:24px}.promo-modal h2{font-size:1.75rem}.promo-modal p{font-size:.86rem}.promo-remaining strong{font-size:2rem}.promo-remaining span{font-size:.78rem}.promo-close{top:12px;right:12px;width:40px;height:40px}.promo-price{gap:.45rem;font-size:.82rem}}
